BEGIN TRANSACTION;
CREATE TABLE "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE "authentication_dashboardslide" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "image" varchar(100) NOT NULL, "title" varchar(120) NOT NULL, "caption" varchar(255) NOT NULL, "display_order" smallint unsigned NOT NULL CHECK ("display_order" >= 0), "is_published" bool NOT NULL);
CREATE TABLE "authentication_halloffameco" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL, "rank" varchar(80) NOT NULL, "photo" varchar(100) NULL, "tenure_start" date NULL, "tenure_end" date NULL, "quote" text NOT NULL, "citation" text NOT NULL, "is_current" bool NOT NULL, "display_order" smallint unsigned NOT NULL CHECK ("display_order" >= 0), "is_published" bool NOT NULL);
CREATE TABLE "authentication_unitachievement" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(160) NOT NULL, "year" varchar(20) NOT NULL, "description" text NOT NULL, "image" varchar(100) NULL, "display_order" smallint unsigned NOT NULL CHECK ("display_order" >= 0), "is_published" bool NOT NULL);
CREATE TABLE "authentication_unithighlight" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(120) NOT NULL, "body" text NOT NULL, "icon" varchar(40) NOT NULL, "display_order" smallint unsigned NOT NULL CHECK ("display_order" >= 0), "is_published" bool NOT NULL);
CREATE TABLE "authentication_unitprofile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "unit_name" varchar(150) NOT NULL, "short_name" varchar(40) NOT NULL, "motto" varchar(200) NOT NULL, "location" varchar(150) NOT NULL, "raised_on" varchar(80) NOT NULL, "war_cry" varchar(120) NOT NULL, "about" text NOT NULL, "crest" varchar(100) NULL);
CREATE TABLE "authentication_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "name" varchar(100) NOT NULL, "appointment" varchar(100) NOT NULL, "sign" varchar(100) NULL, "photo" varchar(100) NULL, "role" varchar(20) NOT NULL, "is_active" bool NOT NULL, "is_staff" bool NOT NULL, "date_joined" datetime NOT NULL, "rank_id" bigint NULL REFERENCES "common_rank" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "authentication_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "authentication_user_organizations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "authentication_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "common_annualperformancereport" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "year" integer unsigned NOT NULL CHECK ("year" >= 0), "report" text NULL, "score" integer unsigned NULL CHECK ("score" >= 0), "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_person_apr_year" UNIQUE ("person_id", "year"));
CREATE TABLE "common_appointmenthistory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "appointment_name" varchar(100) NOT NULL, "start_date" date NOT NULL, "end_date" date NULL, "organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "appointment_valid_dates" CHECK (("end_date" IS NULL OR "end_date" > ("start_date"))));
CREATE TABLE "common_civileducation" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "institution_name" varchar(100) NOT NULL, "from_date" date NOT NULL, "to_date" date NULL, "grade" varchar(100) NULL, "level_id" bigint NOT NULL REFERENCES "common_civileducationlevel" ("id") DEFERRABLE INITIALLY DEFERRED, "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "civil_education_valid_dates" CHECK (("to_date" IS NULL OR "to_date" > ("from_date"))));
CREATE TABLE "common_civileducationlevel" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "level_name" varchar(100) NOT NULL UNIQUE);
CREATE TABLE "common_family" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "relation_name" varchar(150) NOT NULL, "occupation" varchar(150) NOT NULL, "remarks" text NOT NULL, "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "common_medicalcategory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type" varchar(100) NOT NULL, "from_date" date NOT NULL, "to_date" date NULL, "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "medical_category_valid_dates" CHECK (("to_date" IS NULL OR "to_date" > ("from_date"))));
CREATE TABLE "common_mobilenumber" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type_of_number" varchar(20) NOT NULL, "mobile_number" varchar(15) NOT NULL, "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "common_organization" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "organization_name" varchar(100) NOT NULL, "unit_kind" varchar(20) NOT NULL, "authorized_strength" text NOT NULL CHECK ((JSON_VALID("authorized_strength") OR "authorized_strength" IS NULL)), "parent_organization_id" bigint NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_org_name_per_parent" UNIQUE ("organization_name", "parent_organization_id"));
CREATE TABLE "common_person" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(100) NOT NULL, "army_number" varchar(20) NOT NULL UNIQUE, "photo" varchar(100) NULL, "dob" date NOT NULL, "doe" date NOT NULL, "present_age" integer unsigned NULL CHECK ("present_age" >= 0), "present_service_years" integer unsigned NULL CHECK ("present_service_years" >= 0), "al1_13" varchar(3) NULL, "dor" date NULL, "discipline" text NULL, "punishment" text NULL, "mission" bool NOT NULL, "qualification_for_next_rank" bool NOT NULL, "passport_number" varchar(20) NULL UNIQUE, "service_id_card_number" varchar(20) NULL UNIQUE, "present_address" text NULL, "permanent_address" text NULL, "organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "rank_id" bigint NOT NULL REFERENCES "common_rank" ("id") DEFERRABLE INITIALLY DEFERRED, "batch" varchar(30) NOT NULL, "birth_certificate_number" varchar(30) NOT NULL, "height" varchar(30) NOT NULL, "nid_number" varchar(30) NOT NULL, "overweight" varchar(30) NOT NULL, "passport_type" varchar(30) NOT NULL, "phone_imei" varchar(50) NOT NULL, "phone_registration_nid" varchar(30) NOT NULL, "reason_unqualified" text NOT NULL, "social_media_links" text NOT NULL, CONSTRAINT "person_doe_after_dob" CHECK ("doe" > ("dob")));
