CREATE TABLE "common_rank" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "rank_name" varchar(100) NOT NULL UNIQUE, "category" varchar(20) NOT NULL);
CREATE TABLE "common_servicehistory" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "start_date" date NOT NULL, "end_date" date NULL, "organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, "rank_id" bigint NOT NULL REFERENCES "common_rank" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "service_history_valid_dates" CHECK (("end_date" IS NULL OR "end_date" >= ("start_date"))));
CREATE TABLE "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE "duty_dutyassignment" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "assigned_at" datetime NOT NULL, "completed_at" datetime NULL, "status" varchar(20) NOT NULL, "remarks" varchar(255) NOT NULL, "assigned_by_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "soldier_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, "post_id" bigint NOT NULL REFERENCES "duty_dutypost" ("id") DEFERRABLE INITIALLY DEFERRED, "tour_id" bigint NOT NULL REFERENCES "duty_dutytour" ("id") DEFERRABLE INITIALLY DEFERRED, "shift" varchar(10) NOT NULL);
CREATE TABLE "duty_dutypost" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL UNIQUE, "latitude" decimal NOT NULL, "longitude" decimal NOT NULL, "description" varchar(255) NOT NULL, "is_active" bool NOT NULL, "organization_id" bigint NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "duty_type" varchar(20) NOT NULL, "day_strength" integer unsigned NOT NULL CHECK ("day_strength" >= 0), "night_strength" integer unsigned NOT NULL CHECK ("night_strength" >= 0), "display_order" smallint unsigned NOT NULL CHECK ("display_order" >= 0));
CREATE TABLE "duty_dutytour" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "number" integer unsigned NOT NULL CHECK ("number" >= 0), "status" varchar(20) NOT NULL, "opened_at" datetime NOT NULL, "reported_at" datetime NULL, "reported_by_id" bigint NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_duty_tour_number" UNIQUE ("number"));
CREATE TABLE "duty_paradeabsencedocument" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(160) NOT NULL, "document" varchar(100) NOT NULL, "document_date" date NOT NULL, "uploaded_at" datetime NOT NULL, "parade_state_id" bigint NOT NULL REFERENCES "duty_paradestate" ("id") DEFERRABLE INITIALLY DEFERRED, "uploaded_by_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "duty_paradestate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "report_date" date NOT NULL UNIQUE, "authorized_strength" text NOT NULL CHECK ((JSON_VALID("authorized_strength") OR "authorized_strength" IS NULL)), "attachment" varchar(100) NOT NULL, "remarks" varchar(255) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "duty_paradestatecompany" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "posted_strength" text NOT NULL CHECK ((JSON_VALID("posted_strength") OR "posted_strength" IS NULL)), "absent_strength" text NOT NULL CHECK ((JSON_VALID("absent_strength") OR "absent_strength" IS NULL)), "absence_details" text NOT NULL CHECK ((JSON_VALID("absence_details") OR "absence_details" IS NULL)), "organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "parade_state_id" bigint NOT NULL REFERENCES "duty_paradestate" ("id") DEFERRABLE INITIALLY DEFERRED, "authorized_strength" text NOT NULL CHECK ((JSON_VALID("authorized_strength") OR "authorized_strength" IS NULL)), CONSTRAINT "unique_parade_state_company" UNIQUE ("parade_state_id", "organization_id"));
CREATE TABLE "duty_soldierposting" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "posted_at" datetime NOT NULL, "status" varchar(20) NOT NULL, "decided_at" datetime NULL, "remarks" varchar(255) NOT NULL, "accepted_by_id" bigint NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "from_organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, "posted_by_id" bigint NOT NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "soldier_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, "to_organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_assaultcourse" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "attempt" varchar(255) NOT NULL, "date_of_event" date NOT NULL, "time" varchar(255) NOT NULL, "result" varchar(255) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_castrophy" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_of_firing" date NOT NULL, "gp" varchar(255) NOT NULL, "hit" varchar(255) NOT NULL, "total_marks" varchar(255) NOT NULL, "result" varchar(255) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_gpfiring" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type_of_gp" varchar(255) NOT NULL, "attempt" varchar(255) NOT NULL, "date_of_firing" date NOT NULL, "result" varchar(255) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_grenadefiring" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "attempt" varchar(255) NOT NULL, "date_of_firing" date NOT NULL, "result" varchar(255) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_individualcourselevel" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE);
CREATE TABLE "training_individualcoursename" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "level_id" bigint NOT NULL REFERENCES "training_individualcourselevel" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_course_name_per_level" UNIQUE ("level_id", "name"));
CREATE TABLE "training_individualqual" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "spl" varchar(255) NOT NULL, "qual_for_next_promotion" bool NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, "pe" varchar(255) NOT NULL, "year" integer unsigned NOT NULL CHECK ("year" >= 0), CONSTRAINT "unique_person_qual_year" UNIQUE ("solider_id", "year"));
CREATE TABLE "training_individualqualcourse" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "course_name_id" bigint NOT NULL REFERENCES "training_individualcoursename" ("id") DEFERRABLE INITIALLY DEFERRED, "qualification_id" bigint NOT NULL REFERENCES "training_individualqual" ("id") DEFERRABLE INITIALLY DEFERRED, "result" varchar(255) NOT NULL, CONSTRAINT "unique_qual_course" UNIQUE ("qualification_id", "course_name_id"));
CREATE TABLE "training_ipft" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type_of_ipft" varchar(255) NOT NULL, "chance" varchar(255) NOT NULL, "date" date NOT NULL, "result" varchar(255) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_leavestate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "from_date" date NOT NULL, "to_date" date NOT NULL, "no_days" integer unsigned NOT NULL CHECK ("no_days" >= 0), "total_no_days" integer unsigned NOT NULL CHECK ("total_no_days" >= 0), "approved_by_id" bigint NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, "leave_type_id" bigint NOT NULL REFERENCES "training_leavetype" ("id") DEFERRABLE INITIALLY DEFERRED, "applied_by_id" bigint NULL REFERENCES "authentication_user" ("id") DEFERRABLE INITIALLY DEFERRED, "applied_at" datetime NULL, "decided_at" datetime NULL, "remarks" varchar(255) NOT NULL, "status" varchar(20) NOT NULL, "slot" varchar(20) NOT NULL, CONSTRAINT "leave_state_valid_dates" CHECK ("to_date" >= ("from_date")));
CREATE TABLE "training_leavetype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE);
CREATE TABLE "training_participationinmajcom" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "year" integer NOT NULL, "gp_trg" varchar(256) NOT NULL, "st" varchar(256) NOT NULL, "wt" varchar(256) NOT NULL, "fi" varchar(256) NOT NULL, "ihwf" varchar(256) NOT NULL, "ff" varchar(256) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_majcom_per_soldier_year" UNIQUE ("solider_id", "year"));
CREATE TABLE "training_participationinsportstraining" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name_of_comp" varchar(255) NOT NULL, "type_of_comp" varchar(20) NOT NULL, "significant_achievement" varchar(255) NOT NULL, "person_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, "cycle" varchar(20) NOT NULL, "year" integer unsigned NOT NULL CHECK ("year" >= 0));
CREATE TABLE "training_retstate" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "date_performed" date NOT NULL, "result" varchar(255) NOT NULL, "ret_trg_type_id" bigint NOT NULL REFERENCES "training_rettrainingtype" ("id") DEFERRABLE INITIALLY DEFERRED, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_rettrainingtype" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL UNIQUE);
CREATE TABLE "training_sosnfiring" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "type_of_gp" varchar(255) NOT NULL, "attempt" varchar(255) NOT NULL, "date_of_firing" date NOT NULL, "gp" varchar(255) NOT NULL, "hit" varchar(255) NOT NULL, "total_marks" varchar(255) NOT NULL, "result" varchar(255) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_speedmarch" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "attempt" varchar(255) NOT NULL, "date_of_event" date NOT NULL, "result" varchar(255) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "training_unittrainingcycleplan" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "year" integer unsigned NOT NULL CHECK ("year" >= 0), "cycle" smallint unsigned NOT NULL CHECK ("cycle" >= 0), "bde_lvl_cadre" text NOT NULL, "div_lvl_cadre" text NOT NULL, "pre_course_pe" text NOT NULL, "gpt" text NOT NULL, "misc_trg_event" text NOT NULL, "organization_id" bigint NOT NULL REFERENCES "common_organization" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_unit_training_cycle_per_company_year" UNIQUE ("year", "cycle", "organization_id"));
CREATE TABLE "training_yearlyplan" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "year" integer NOT NULL, "cycle" varchar(20) NOT NULL, "option" varchar(20) NOT NULL, "solider_id" bigint NOT NULL REFERENCES "common_person" ("id") DEFERRABLE INITIALLY DEFERRED, CONSTRAINT "unique_yearly_plan_cycle" UNIQUE ("solider_id", "year", "cycle"));
