INSERT INTO "authentication_unitprofile" VALUES(1,'1 Bangladesh Infantry Regiment','1 BIR','Powerful, Fast, Superior','Ramu Cantonment, Cox''s Bazar','21 April 2001','Joy Bangla','Role & Function: Serves as the pioneer battalion of the Bangladesh Infantry Regiment. It is structured for conventional land warfare, border security, counter-insurgency operations, domestic disaster response, and United Nations (UN) peacekeeping deployments.  Historical Context: Prior to 2001, the East Bengal Regiment was the sole infantry regiment of the Bangladesh Army. 1 BIR was established by initial conversions from existing forces alongside fresh recruitments to build a secondary combat infantry pillar.  Regimental Center: Headquartered under the Bangladesh Infantry Regimental Centre (BIRC) located at Rajshahi Cantonment.','');
